std::vector<Node> path;
std::vector<Node*> open_list;
std::unordered_map<int, bool> closed_list;

Node& start_node = graph.SNodes()[start_idx];
Node& end_node = graph.SNodes()[end_idx];

start_node.g_value = 0.0f;
start_node.h_value = start_node.distance(end_node);
start_node.visited = true;
open_list.push_back(&start_node);

while (!open_list.empty()) {
    Node* current_node = nullptr;
    float lowest_f = std::numeric_limits<float>::max();
    int lowest_index = -1;

    for (int i = 0; i < open_list.size(); ++i) {
        float f_value = open_list[i]->g_value + open_list[i]->h_value;
        if (f_value < lowest_f) {
            lowest_f = f_value;
            lowest_index = i;
            current_node = open_list[i];
        }
    }

    if (current_node == nullptr) break;

    if (current_node == &end_node) {
        path = construct_final_path(current_node);
        break;
    }

    open_list.erase(open_list.begin() + lowest_index);
    closed_list[current_node->index_] = true;

    current_node->find_neighbors();

    for (Node* neighbor : current_node->neighbors) {
        if (closed_list[neighbor->index_]) continue;

        float tentative_g = current_node->g_value + current_node->distance(*neighbor);

        if (tentative_g < neighbor->g_value) {
            neighbor->parent = current_node;
            neighbor->g_value = tentative_g;
            neighbor->h_value = neighbor->distance(end_node);

            if (!neighbor->visited) {
                neighbor->visited = true;
                open_list.push_back(neighbor);
            }
        }
    }
}

return path;

